import{_ as t,o as d,c as o,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Integrations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/integrations.md","filePath":"src/en/guide/integrations.md"}'),r={name:"en/guide/integrations.md"};function n(s,e,i,c,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="integrations" tabindex="-1">Integrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Integrations&quot;">​</a></h1><p>Kura sits at the centre of three flows: the NextBoxx website <strong>sends</strong> it candidatures, requests and registrations; Sève <strong>gets</strong> its identity from Kura and receives its changes; WhatsApp and PayGate complete notifications and payments.</p><h2 id="nextboxx-website-api" tabindex="-1">NextBoxx website API <a class="header-anchor" href="#nextboxx-website-api" aria-label="Permalink to &quot;NextBoxx website API&quot;">​</a></h2><p>The website calls Kura <strong>from its server</strong>, never from the browser, with a dedicated API key in the <code>Authorization: Bearer &lt;key&gt;</code> header. The key is <code>NEXTBOXX_SITE_API_KEY</code> on Kura&#39;s side, <code>KURA_SITE_API_KEY</code> on the website&#39;s side. Limit: 60 requests per minute.</p><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Effect</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/candidatures</code></td><td>Creates or reuses the account, opens the candidature, returns <code>tracking_token</code></td></tr><tr><td><code>GET</code></td><td><code>/api/candidatures/status</code></td><td>Status of a file from the <code>tracking_token</code>, without pulling the data back</td></tr><tr><td><code>GET</code></td><td><code>/api/events</code></td><td>Published upcoming events, with remaining seats and payment deadline</td></tr><tr><td><code>POST</code></td><td><code>/api/events/{event}/registrations</code></td><td>Registers a participant, confirms, puts on payment hold or on the waiting list</td></tr><tr><td><code>POST</code></td><td><code>/api/company-requests</code></td><td>Submits a B2B training request</td></tr><tr><td><code>GET</code></td><td><code>/api/partnerships</code></td><td>Active technology partnerships, by programme</td></tr></tbody></table><p>Notable response codes:</p><ul><li><code>401</code>: missing or invalid key.</li><li><code>409</code>: <code>COOLING_OFF</code> (resubmission too soon after a refusal), <code>CANDIDATURE_IN_PROGRESS</code>, <code>EVENT_CLOSED</code>, <code>ALREADY_REGISTERED</code>, <code>ACCOUNT_SUSPENDED</code>.</li><li><code>422</code>: validation (unknown or unpublished programme, format not offered, invalid referral code…).</li></ul><p>An accepted response is copied into the website CMS with its identifier; on error, the website keeps nothing and the candidate resubmits.</p><h2 id="oauth2-openid-connect-for-seve" tabindex="-1">OAuth2 / OpenID Connect for Sève <a class="header-anchor" href="#oauth2-openid-connect-for-seve" aria-label="Permalink to &quot;OAuth2 / OpenID Connect for Sève&quot;">​</a></h2><p>Kura is the identity provider. Sève stores no Moodle password.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Role</th></tr></thead><tbody><tr><td><code>GET /oauth2/authorize</code></td><td>Redirects to the Kura sign-in, then to Sève with a code</td></tr><tr><td><code>POST /oauth2/token</code></td><td>Exchanges the code for an access token (1 hour) and a refresh token (30 days)</td></tr><tr><td><code>GET /oauth2/userinfo</code></td><td>Returns <code>sub</code>, <code>email</code>, <code>email_verified</code>, <code>name</code>, <code>given_name</code>, <code>family_name</code></td></tr></tbody></table><ul><li>Client registered by <code>php artisan seve:client</code>, with the return URL <code>{SEVE_URL}/admin/oauth2callback.php</code>. The secret is shown only once.</li><li>Only <code>active</code> or <code>canope</code> accounts can sign in; a <code>suspended</code> account receives <code>403</code>.</li><li>No OpenID Connect identity token: Moodle reads <code>userinfo</code> and matches accounts by email.</li><li>The OAuth keys (<code>storage/oauth-*.key</code>) are critical: losing them signs every Sève user out.</li></ul><h2 id="seve-web-services" tabindex="-1">Sève web services <a class="header-anchor" href="#seve-web-services" aria-label="Permalink to &quot;Sève web services&quot;">​</a></h2><p>Kura calls Sève; Sève does not call Kura. Calls go through an external service “Kura Integration”, with the token of a service account (<code>SEVE_WS_TOKEN</code>), over REST.</p><h3 id="provisioning" tabindex="-1">Provisioning <a class="header-anchor" href="#provisioning" aria-label="Permalink to &quot;Provisioning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Moodle function</th><th>Trigger</th></tr></thead><tbody><tr><td><code>core_user_create_users</code></td><td>First instalment paid, all shares included — <code>auth=oauth2</code>, without a password</td></tr><tr><td><code>core_user_update_users</code></td><td>Status change: suspension, reactivation, Canopé</td></tr><tr><td><code>enrol_manual_enrol_users</code></td><td>Enrolment in the cohort course, or in the Parcours Canopé course on certification</td></tr><tr><td><code>enrol_manual_unenrol_users</code></td><td>Withdrawal, or switch to Canopé</td></tr><tr><td><code>core_user_get_users_by_field</code></td><td>Find a Moodle account by email, to make a replay idempotent</td></tr></tbody></table><p>Changes go through a <strong>replayable queue</strong> (<code>integration_events</code>). A failure stays pending with its error; the Administrator is alerted on the fifth failure. <code>seve:sync</code> sends the queue every minute, in order for a given account.</p><h3 id="partners-and-messages" tabindex="-1">Partners and messages <a class="header-anchor" href="#partners-and-messages" aria-label="Permalink to &quot;Partners and messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Trigger</th></tr></thead><tbody><tr><td><code>core_course_get_courses</code> / <code>core_course_update_courses</code></td><td><code>seve:partners</code>, every hour: “Partners” block in the course summary, without touching the rest</td></tr><tr><td><code>core_message_send_instant_messages</code></td><td>Announcement or reminder to an account with a Moodle identifier</td></tr></tbody></table><h3 id="pull" tabindex="-1">Pull <a class="header-anchor" href="#pull" aria-label="Permalink to &quot;Pull&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Feeds</th><th>Frequency</th></tr></thead><tbody><tr><td><code>core_completion_get_course_completion_status</code></td><td>Progress</td><td>Scheduled</td></tr><tr><td><code>gradereport_user_get_grade_items</code></td><td>Per-block grades (<code>KURA-BLOC-{id}</code>)</td><td><code>seve:pull</code>, every hour</td></tr><tr><td><code>core_course_get_contents</code> + <code>mod_attendance_get_sessions</code></td><td>Attendance</td><td><code>seve:pull</code>, every hour</td></tr></tbody></table><p>Attendance status mapping: <code>P</code> present; <code>L</code> or <code>R</code> late; <code>A</code>, <code>E</code> and anything else absent. An excused absence remains an absence for the 30% threshold.</p><h2 id="whatsapp-business-cloud-api" tabindex="-1">WhatsApp Business Cloud API <a class="header-anchor" href="#whatsapp-business-cloud-api" aria-label="Permalink to &quot;WhatsApp Business Cloud API&quot;">​</a></h2><p><code>POST https://graph.facebook.com/{WHATSAPP_API_VERSION}/{WHATSAPP_PHONE_NUMBER_ID}/messages</code>, with <code>Authorization: Bearer {WHATSAPP_TOKEN}</code>. Message of type <code>template</code>, in the recipient&#39;s language (<code>fr</code> or <code>en</code>).</p><table tabindex="0"><thead><tr><th>Template</th><th>Notification</th></tr></thead><tbody><tr><td><code>kura_invoice_reminder</code></td><td>Due-date reminder (D-15, D-7, D-1)</td></tr><tr><td><code>kura_invoice_unpaid</code></td><td>D+1 reminder</td></tr><tr><td><code>kura_invoice_overdue</code></td><td>Overdue status and moratorium</td></tr><tr><td><code>kura_access_suspended</code></td><td>D+30 suspension</td></tr><tr><td><code>kura_access_restored</code></td><td>Reactivation</td></tr><tr><td><code>kura_candidature_admitted</code></td><td>“Admitted” decision</td></tr><tr><td><code>kura_candidature_refused</code></td><td>“Refused” decision</td></tr><tr><td><code>kura_candidature_overdue</code></td><td>Overdue candidature step</td></tr></tbody></table><p>As long as <code>WHATSAPP_TOKEN</code> and <code>WHATSAPP_PHONE_NUMBER_ID</code> are empty, messages go out by email only. A WhatsApp failure does not block email.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>A single engine, three channels:</p><table tabindex="0"><thead><tr><th>Channel</th><th>When</th></tr></thead><tbody><tr><td>Email</td><td>Always</td></tr><tr><td>Sève</td><td>Accounts opened in Sève (Moodle message from the service account)</td></tr><tr><td>WhatsApp</td><td>Payment and admission reminders, if the account has a phone number</td></tr></tbody></table><p>Every delivery is recorded in <code>notification_deliveries</code> (recipient, type, channel, status, error, date). The log is filterable by channel and status, with the number of failures over the last 30 days.</p><p>Triggers: payment (D-15/D-7/D-1, D+1, overdue, suspension, reactivation), admission (interview, test, decision), roles, certification, attendance, B2B training, matching, events, event funding, partnerships and generated documents.</p><h2 id="online-payment-planned" tabindex="-1">Online payment (planned) <a class="header-anchor" href="#online-payment-planned" aria-label="Permalink to &quot;Online payment (planned)&quot;">​</a></h2><p>PayGate (Flooz, T-Money) is the provider chosen by ADR-006. The contract plans a callback on <code>POST /api/paiements/callback</code>, which will update the invoice and the payment, then trigger the effects: Sève provisioning when all shares of the first instalment are paid, suspension lifted, referrer commission.</p><p>Until that wiring exists in <code>kura-web</code>, payments are entered manually by the Coordinator and no external caller touches invoices.</p><h2 id="commands-and-scheduling" tabindex="-1">Commands and scheduling <a class="header-anchor" href="#commands-and-scheduling" aria-label="Permalink to &quot;Commands and scheduling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Frequency</th><th>Purpose</th></tr></thead><tbody><tr><td><code>seve:sync</code></td><td>Every minute</td><td>Sends pending changes to Sève</td></tr><tr><td><code>seve:pull</code></td><td>Every hour</td><td>Reads attendance and grades of running cohorts</td></tr><tr><td><code>seve:partners</code></td><td>Every hour</td><td>Updates the “Partners” block of the courses</td></tr><tr><td><code>billing:run</code></td><td>Daily</td><td>Issues due instalments, reminders, moratoriums, suspensions</td></tr><tr><td><code>events:run</code></td><td>Hourly</td><td>Cancels registrations unpaid at 48 hours</td></tr><tr><td><code>cohorts:advance</code></td><td>Daily</td><td>Starts and completes cohorts</td></tr><tr><td><code>candidatures:remind</code></td><td>Daily</td><td>Reminds about overdue candidature steps</td></tr><tr><td><code>candidatures:anonymize</code></td><td>Daily</td><td>Anonymises candidatures refused 12 months ago</td></tr><tr><td><code>accounts:deactivate-inactive</code></td><td>Daily</td><td>Deactivates accounts inactive for a year</td></tr><tr><td><code>partnerships:end</code></td><td>Daily</td><td>Ends expired partnerships</td></tr><tr><td><code>passport:purge</code></td><td>Daily</td><td>Purges expired OAuth tokens</td></tr></tbody></table>',36)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
